using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ReliefDefaultEffectAction", menuName = "Data/Battle/Battle Actions/Sothis/ReliefDefaultEffect Action")]
public class ReliefDefaultEffectAction : DefaultEffectAction
{
	[Header("Soul Heat")]
	[SerializeField]
	private SoulHeat soulHeat;

	public override void AreaCastTargetAmount(List<GameObject> targets, int amount, GameObject source)
	{
		CheckIncreaseSoulHeat(source);
		base.AreaCastTargetAmount(targets, amount, source);
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		CheckIncreaseSoulHeat(source);
		base.CastTargetAmount(target, amount, source);
	}

	private void CheckIncreaseSoulHeat(GameObject source)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source))
		{
			soulHeat.ModifySoulHeat(1);
		}
	}
}
